// Command svc serves the items API.
package main

import (
	"log"
	"os"

	"example.com/svc/config"
	"example.com/svc/server"
	"example.com/svc/store"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatal(err)
	}
	logger := log.New(os.Stderr, "svc ", log.LstdFlags)
	st := store.NewMemStore()
	srv := server.New(cfg, st, logger)
	logger.Printf("listening on %s (log level %s)", cfg.Addr, cfg.LogLevel)
	if err := srv.HTTPServer().ListenAndServe(); err != nil {
		logger.Fatal(err)
	}
}

