// Package config reads the service configuration from the environment.
package config

import (
	"fmt"
	"os"
	"strings"
)

// Config is everything the service needs to start.
type Config struct {
	// Addr is the listen address, host:port.
	Addr string
	// DBPath is where the store persists, or "" for memory only.
	DBPath string
	// LogLevel is one of debug, info, warn, error.
	LogLevel string
}

// Defaults are used for every variable that is unset.
var Defaults = Config{Addr: ":8080", DBPath: "", LogLevel: "info"}

// Load reads SVC_ADDR, SVC_DB and SVC_LOG_LEVEL, falling back to Defaults,
// and validates the result.
func Load() (Config, error) {
	c := Defaults
	if v := os.Getenv("SVC_ADDR"); v != "" {
		c.Addr = v
	}
	if v := os.Getenv("SVC_DB"); v != "" {
		c.DBPath = v
	}
	if v := os.Getenv("SVC_LOG_LEVEL"); v != "" {
		c.LogLevel = strings.ToLower(v)
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

// Validate checks the values without touching the environment.
func (c Config) Validate() error {
	if c.Addr == "" || !strings.Contains(c.Addr, ":") {
		return fmt.Errorf("config: SVC_ADDR %q must be host:port", c.Addr)
	}
	switch c.LogLevel {
	case "debug", "info", "warn", "error":
	default:
		return fmt.Errorf("config: SVC_LOG_LEVEL %q must be debug, info, warn or error", c.LogLevel)
	}
	return nil
}

