package config

import "testing"

func TestLoadDefaults(t *testing.T) {
	t.Setenv("SVC_ADDR", "")
	t.Setenv("SVC_DB", "")
	t.Setenv("SVC_LOG_LEVEL", "")
	c, err := Load()
	if err != nil {
		t.Fatal(err)
	}
	if c != Defaults {
		t.Fatalf("got %+v want %+v", c, Defaults)
	}
}

func TestLoadOverridesAndValidates(t *testing.T) {
	t.Setenv("SVC_ADDR", "127.0.0.1:9090")
	t.Setenv("SVC_LOG_LEVEL", "DEBUG")
	c, err := Load()
	if err != nil || c.Addr != "127.0.0.1:9090" || c.LogLevel != "debug" {
		t.Fatalf("c=%+v err=%v", c, err)
	}
	t.Setenv("SVC_LOG_LEVEL", "loud")
	if _, err := Load(); err == nil {
		t.Fatal("bad log level accepted")
	}
	t.Setenv("SVC_LOG_LEVEL", "info")
	t.Setenv("SVC_ADDR", "nope")
	if _, err := Load(); err == nil {
		t.Fatal("bad addr accepted")
	}
}

