package server

import (
	"encoding/json"
	"io"
	"log"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"example.com/svc/config"
	"example.com/svc/store"
)

func newTestServer(t *testing.T) *httptest.Server {
	t.Helper()
	s := New(config.Defaults, store.NewMemStore(), log.New(io.Discard, "", 0))
	ts := httptest.NewServer(s.Handler())
	t.Cleanup(ts.Close)
	return ts
}

func TestCreateGetListDelete(t *testing.T) {
	ts := newTestServer(t)
	resp, err := http.Post(ts.URL+"/items", "application/json", strings.NewReader(`{"id":"p1","name":"pen","tags":["office"]}`))
	if err != nil || resp.StatusCode != http.StatusCreated {
		t.Fatalf("create: %v %v", err, resp.Status)
	}
	resp, _ = http.Post(ts.URL+"/items", "application/json", strings.NewReader(`{"id":"p1","name":"pen"}`))
	if resp.StatusCode != http.StatusConflict {
		t.Fatalf("duplicate: %s", resp.Status)
	}
	resp, _ = http.Post(ts.URL+"/items", "application/json", strings.NewReader(`{"id":"","name":"x"}`))
	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("empty id: %s", resp.Status)
	}
	resp, _ = http.Get(ts.URL + "/items/p1")
	var it store.Item
	if err := json.NewDecoder(resp.Body).Decode(&it); err != nil || it.Name != "pen" {
		t.Fatalf("get: %+v %v", it, err)
	}
	resp, _ = http.Get(ts.URL + "/items?tag=office")
	var list []store.Item
	if err := json.NewDecoder(resp.Body).Decode(&list); err != nil || len(list) != 1 {
		t.Fatalf("list by tag: %+v %v", list, err)
	}
	req, _ := http.NewRequest(http.MethodDelete, ts.URL+"/items/p1", nil)
	resp, _ = http.DefaultClient.Do(req)
	if resp.StatusCode != http.StatusNoContent {
		t.Fatalf("delete: %s", resp.Status)
	}
	resp, _ = http.Get(ts.URL + "/items/p1")
	if resp.StatusCode != http.StatusNotFound {
		t.Fatalf("after delete: %s", resp.Status)
	}
}

func TestHTTPServerUsesConfiguredAddr(t *testing.T) {
	cfg := config.Defaults
	cfg.Addr = "127.0.0.1:0"
	hs := New(cfg, store.NewMemStore(), log.New(io.Discard, "", 0)).HTTPServer()
	if hs.Addr != "127.0.0.1:0" || hs.ReadTimeout == 0 || hs.WriteTimeout == 0 {
		t.Fatalf("server = %+v", hs)
	}
}

