// Package store keeps items. The only implementation today is in memory;
// the interface is what the server programs against.
package store

import (
	"errors"
	"sort"
	"sync"
	"time"
)

// Item is one stored record.
type Item struct {
	ID      string    `json:"id"`
	Name    string    `json:"name"`
	Tags    []string  `json:"tags,omitempty"`
	Created time.Time `json:"created"`
}

// ErrNotFound is returned for an unknown id.
var ErrNotFound = errors.New("store: not found")

// ErrExists is returned when an id is already taken.
var ErrExists = errors.New("store: already exists")

// Store is what the server needs from a backend.
type Store interface {
	Put(item Item) error
	Get(id string) (Item, error)
	List() []Item
	Delete(id string) error
}

// MemStore is a Store held in a map, safe for concurrent use.
type MemStore struct {
	mu    sync.RWMutex
	items map[string]Item
}

// NewMemStore returns an empty MemStore.
func NewMemStore() *MemStore {
	return &MemStore{items: map[string]Item{}}
}

// Put stores a new item; it fails if the id exists.
func (s *MemStore) Put(item Item) error {
	if item.ID == "" {
		return errors.New("store: empty id")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.items[item.ID]; ok {
		return ErrExists
	}
	if item.Created.IsZero() {
		item.Created = time.Now().UTC()
	}
	s.items[item.ID] = item
	return nil
}

// Get returns the item with id.
func (s *MemStore) Get(id string) (Item, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	it, ok := s.items[id]
	if !ok {
		return Item{}, ErrNotFound
	}
	return it, nil
}

// List returns every item sorted by id.
func (s *MemStore) List() []Item {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]Item, 0, len(s.items))
	for _, it := range s.items {
		out = append(out, it)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// Delete removes the item with id.
func (s *MemStore) Delete(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.items[id]; !ok {
		return ErrNotFound
	}
	delete(s.items, id)
	return nil
}

// Len is the number of items, for tests and metrics.
func (s *MemStore) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.items)
}

