package store

import (
	"errors"
	"testing"
)

func TestMemStoreRoundTrip(t *testing.T) {
	s := NewMemStore()
	if err := s.Put(Item{ID: "b", Name: "second"}); err != nil {
		t.Fatal(err)
	}
	if err := s.Put(Item{ID: "a", Name: "first", Tags: []string{"x"}}); err != nil {
		t.Fatal(err)
	}
	if err := s.Put(Item{ID: "a"}); !errors.Is(err, ErrExists) {
		t.Fatalf("duplicate: %v", err)
	}
	if err := s.Put(Item{}); err == nil {
		t.Fatal("empty id accepted")
	}
	got, err := s.Get("a")
	if err != nil || got.Name != "first" || got.Created.IsZero() {
		t.Fatalf("get: %+v %v", got, err)
	}
	if l := s.List(); len(l) != 2 || l[0].ID != "a" || l[1].ID != "b" {
		t.Fatalf("list: %+v", l)
	}
	if err := s.Delete("a"); err != nil || s.Len() != 1 {
		t.Fatalf("delete: %v len=%d", err, s.Len())
	}
	if _, err := s.Get("a"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("after delete: %v", err)
	}
	if err := s.Delete("zzz"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("delete missing: %v", err)
	}
}
